const DL_CHARMS=[...Object.entries(CHARM_PHOTOS).map(([k,v])=>[k,v.n]),['none','sin charm']];
/* a photo charm hanging from its jump ring, same 40×60 box as the drawn charms */
function charmPhotoSVG(ch,w){const p=CHARM_PHOTOS[ch.shape],k=Math.min(32/p.w,40/p.h),iw=p.w*k,ih=p.h*k;
  return `<svg viewBox="0 0 40 60" width="${w}" height="${w*1.5}" style="overflow:visible"><g filter="drop-shadow(1px 2px 1.5px rgba(0,0,0,.45))"><circle cx="20" cy="6" r="4" fill="none" stroke="#c9a24a" stroke-width="2"/><path d="M20 10v8" stroke="#c9a24a" stroke-width="1.6" stroke-dasharray="2 1.2"/><image href="${p.src}" x="${20-iw/2}" y="17" width="${iw}" height="${ih}"/></g></svg>`}
